import sys
from http.server import BaseHTTPRequestHandler, HTTPServer
import json

store = {}

class RequestHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        content_length = int(self.headers['Content-Length'])
        post_data = self.rfile.read(content_length)
        target = self.headers.get('X-Amz-Target', '')

        print(f"Target: {target}", flush=True)
        try:
            body = json.loads(post_data.decode('utf-8'))
            print(f"Body: {json.dumps(body)}", flush=True)
        except:
            body = {}

        response_data = {}
        if target == 'AmazonSSM.PutParameter':
            name = body.get('Name')
            val = body.get('Value')
            store[name] = val
            response_data = {"Version": 1}
        elif target == 'AmazonSSM.GetParameters':
            names = body.get('Names', [])
            params = []
            for n in names:
                if n in store:
                    params.append({"Name": n, "Value": store[n], "Version": 1})
            response_data = {"Parameters": params, "InvalidParameters": [n for n in names if n not in store]}
        elif target == 'AmazonSSM.DescribeParameters':
            filters = body.get('ParameterFilters', [])
            params = []
            for k, v in store.items():
                params.append({"Name": k, "Version": 1, "LastModifiedDate": 1000000.0, "LastModifiedUser": "arn:aws:iam::123:user/me"})
            response_data = {"Parameters": params}
        elif target == 'AmazonSSM.GetParametersByPath':
            path = body.get('Path')
            params = []
            for k, v in store.items():
                if k.startswith(path):
                    params.append({"Name": k, "Value": v, "Version": 1})
            response_data = {"Parameters": params}

        self.send_response(200)
        self.send_header('Content-Type', 'application/x-amz-json-1.1')
        self.end_headers()
        self.wfile.write(json.dumps(response_data).encode('utf-8'))

if __name__ == '__main__':
    server = HTTPServer(('localhost', 8080), RequestHandler)
    server.serve_forever()
