{"command":"cat << 'EOF' > my_chamber.py
#!/usr/bin/env python3
import sys
import os
import datetime
import hashlib
import hmac
import json
import urllib.request
import urllib.error
import math
from helps import HELPS

def sign(key, msg):
    return hmac.new(key, msg.encode('utf-8'), hashlib.sha256).digest()

def get_signature_key(key, dateStamp, regionName, serviceName):
    kDate = sign(('AWS4' + key).encode('utf-8'), dateStamp)
    kRegion = sign(kDate, regionName)
    kService = sign(kRegion, serviceName)
    return sign(kService, 'aws4_request')

def send_ssm_request(target, payload):
    method = 'POST'
    service = 'ssm'
    region = os.environ.get('AWS_REGION', 'us-east-1')
    endpoint = os.environ.get('AWS_ENDPOINT_URL', f'https://ssm.{region}.amazonaws.com')

    if endpoint.startswith('http://'):
        host = endpoint.split('http://')[1].split('/')[0]
    elif endpoint.startswith('https://'):
        host = endpoint.split('https://')[1].split('/')[0]
    else:
        host = endpoint

    access_key = os.environ.get('AWS_ACCESS_KEY_ID', 'test')
    secret_key = os.environ.get('AWS_SECRET_ACCESS_KEY', 'test')
    session_token = os.environ.get('AWS_SESSION_TOKEN', '')

    t = datetime.datetime.utcnow()
    amzdate = t.strftime('%Y%m%dT%H%M%SZ')
    datestamp = t.strftime('%Y%m%d')

    canonical_uri = '/'
    canonical_querystring = ''
    payload_hash = hashlib.sha256(payload.encode('utf-8')).hexdigest()

    headers = {
        'Content-Type': 'application/x-amz-json-1.1',
        'Host': host,
        'X-Amz-Date': amzdate,
        'X-Amz-Target': target,
    }
    if session_token:
        headers['X-Amz-Security-Token'] = session_token

    canonical_headers = ''
    signed_headers = ''
    for k in sorted(headers.keys()):
        canonical_headers += f"{k.lower()}:{headers[k]}\n"
        signed_headers += f"{k.lower()};"
    signed_headers = signed_headers[:-1]

    canonical_request = f"{method}\n{canonical_uri}\n{canonical_querystring}\n{canonical_headers}\n{signed_headers}\n{payload_hash}"

    algorithm = 'AWS4-HMAC-SHA256'
    credential_scope = f"{datestamp}/{region}/{service}/aws4_request"
    string_to_sign = f"{algorithm}\n{amzdate}\n{credential_scope}\n{hashlib.sha256(canonical_request.encode('utf-8')).hexdigest()}"

    signing_key = get_signature_key(secret_key, datestamp, region, service)
    signature = hmac.new(signing_key, string_to_sign.encode('utf-8'), hashlib.sha256).hexdigest()

    headers['Authorization'] = f"{algorithm} Credential={access_key}/{credential_scope}, SignedHeaders={signed_headers}, Signature={signature}"

    req = urllib.request.Request(endpoint, data=payload.encode('utf-8'), headers=headers)
    try:
        resp = urllib.request.urlopen(req)
        return json.loads(resp.read().decode('utf-8'))
    except urllib.error.HTTPError as e:
        body = e.read().decode('utf-8')
        try:
            err = json.loads(body)
            msg = err.get('message', err.get('Message', body))
            print(f"Error: {msg}", file=sys.stderr)
        except:
            print(f"Error: {body}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error: {str(e)}", file=sys.stderr)
        sys.exit(1)

def describe_parameters(service):
    params = []
    next_token = None
    while True:
        req = {"ParameterFilters": [{"Key": "Path", "Option": "OneLevel", "Values": [f"/{service}"]}]}
        if next_token: req["NextToken"] = next_token
        res = send_ssm_request("AmazonSSM.DescribeParameters", json.dumps(req))
        params.extend(res.get("Parameters", []))
        next_token = res.get("NextToken")
        if not next_token: break
    return params

def get_parameters_by_path(service):
    params = []
    next_token = None
    while True:
        req = {"Path": f"/{service}/", "WithDecryption": True}
        if next_token: req["NextToken"] = next_token
        res = send_ssm_request("AmazonSSM.GetParametersByPath", json.dumps(req))
        params.extend(res.get("Parameters", []))
        next_token = res.get("NextToken")
        if not next_token: break
    return params

def get_parameters(names):
    if not names: return []
    req = {"Names": names, "WithDecryption": True}
    res = send_ssm_request("AmazonSSM.GetParameters", json.dumps(req))
    return res.get("Parameters", [])

def format_date(ts):
    if not ts: return "1970-01-01 00:00:00"
    try:
        dt = datetime.datetime.utcfromtimestamp(ts)
        return dt.strftime('%Y-%m-%d %H:%M:%S')
    except:
        return "1970-01-01 00:00:00"

def format_table(rows):
    if not rows: return ''
    col_widths = []
    for r in rows:
        for i, c in enumerate(r):
            if i >= len(col_widths): col_widths.append(0)
            col_widths[i] = max(col_widths[i], len(str(c)))

    out = ''
    for r in rows:
        row_str = ''
        for i, c in enumerate(r):
            row_str += str(c)
            if i < len(r) - 1:
                col_width = math.ceil((col_widths[i] + 2) / 8.0) * 8
                cur_len = len(str(c))
                while cur_len < col_width:
                    row_str += '\t'
                    cur_len = math.ceil((cur_len + 1) / 8.0) * 8
        out += row_str + '\n'
    return out

def main():
    if len(sys.argv) < 2 or sys.argv[1] in ('-h', '--help', 'help'):
        print(HELPS.get("", ""), end='')
        return

    cmd = sys.argv[1]

    if cmd == 'version':
        print("chamber dev")
        return

    if '--help' in sys.argv or '-h' in sys.argv:
        full_cmd = cmd
        if cmd == 'tag' and len(sys.argv) > 2 and sys.argv[2] in ('delete', 'read', 'write'):
            full_cmd = f"tag {sys.argv[2]}"
        print(HELPS.get(full_cmd, ""), end='')
        return

    if cmd == 'list':
        expose = '-e' in sys.argv
        args = [a for a in sys.argv[2:] if not a.startswith('-')]
        if not args: return
        service = args[0]
        desc = describe_parameters(service)
        desc.sort(key=lambda x: x['Name'])

        val_map = {}
        if expose:
            if desc:
                vals = get_parameters([p['Name'] for p in desc])
                val_map = {p['Name']: p['Value'] for p in vals}

        rows = []
        if expose:
            rows.append(['Key', 'Version', 'LastModified', 'User', 'Value'])
        else:
            rows.append(['Key', 'Version', 'LastModified', 'User'])

        for p in desc:
            key = p['Name'].split('/')[-1]
            ver = "0"
            ts = format_date(p.get('LastModifiedDate', 0))
            user = p.get('LastModifiedUser', '')
            if expose:
                val = val_map.get(p['Name'], '')
                rows.append([key, ver, ts, user, val])
            else:
                rows.append([key, ver, ts, user])
        print(format_table(rows), end='')

    elif cmd == 'read':
        quiet = '-q' in sys.argv or '--quiet' in sys.argv
        args = [a for a in sys.argv[2:] if not a.startswith('-')]
        if len(args) < 2: return
        service, key = args[0], args[1]
        name = f"/{service}/{key}"

        vals = get_parameters([name])
        if not vals:
            print("Error: Failed to read: secret not found", file=sys.stderr)
            sys.exit(1)
        val = vals[0]['Value']

        if quiet:
            print(val)
        else:
            desc = describe_parameters(service)
            p = next((x for x in desc if x['Name'] == name), {})
            ver = "0"
            ts = format_date(p.get('LastModifiedDate', 0)) if p else "1970-01-01 00:00:00"
            user = p.get('LastModifiedUser', '') if p else ""
            rows = [
                ['Key', 'Value', 'Version', 'LastModified', 'User'],
                [key, val, ver, ts, user]
            ]
            print(format_table(rows), end='')

    elif cmd == 'history':
        args = [a for a in sys.argv[2:] if not a.startswith('-')]
        if len(args) < 2: return
        service, key = args[0], args[1]
        name = f"/{service}/{key}"
        req = {"Name": name, "WithDecryption": False}
        res = send_ssm_request("AmazonSSM.GetParameterHistory", json.dumps(req))
        hist = res.get("Parameters", [])

        rows = [['Event', 'Version', 'Date', 'User']]
        for p in hist:
            event = 'Updated'
            ver = "0"
            ts = format_date(p.get('LastModifiedDate', 0))
            user = p.get('LastModifiedUser', '')
            rows.append([event, ver, ts, user])
        print(format_table(rows), end='')

    elif cmd == 'env':
        args = [a for a in sys.argv[2:] if not a.startswith('-')]
        if not args: return
        service = args[0]
        params = get_parameters_by_path(service)
        params.sort(key=lambda x: x['Name'])
        for p in params:
            key = p['Name'].split('/')[-1]
            if '-p' not in sys.argv and '--preserve-case' not in sys.argv:
                key = key.upper()
            val = p['Value']
            print(f"export {key}={val}")

    elif cmd == 'export':
        args = [a for a in sys.argv[2:] if not a.startswith('-')]
        if not args: return
        service = args[0]
        params = get_parameters_by_path(service)
        out = {}
        for p in params:
            key = p['Name'].split('/')[-1]
            out[key] = p['Value']
        print(json.dumps(out))

    elif cmd == 'delete':
        args = [a for a in sys.argv[2:] if not a.startswith('-')]
        if len(args) < 2: return
        service, key = args[0], args[1]
        name = f"/{service}/{key}"
        req = {"Name": name}
        send_ssm_request("AmazonSSM.DeleteParameter", json.dumps(req))

    elif cmd == 'write':
        args = []
        tags = []
        i = 2
        while i < len(sys.argv):
            if sys.argv[i] in ('-t', '--tags'):
                if i + 1 < len(sys.argv):
                    tags = sys.argv[i+1].split(',')
                    i += 2
                else:
                    i += 1
                continue
            if sys.argv[i].startswith('--tags='):
                tags = sys.argv[i].split('=', 1)[1].split(',')
                i += 1
                continue
            if sys.argv[i].startswith('-') and sys.argv[i] != '-':
                i += 1
                continue
            args.append(sys.argv[i])
            i += 1

        if len(args) < 3: return
        service, key, value = args[0], args[1], args[2]
        if value == '-':
            value = sys.stdin.read()
        name = f"/{service}/{key}"

        req = {
            "Description": "1",
            "Name": name,
            "Value": value,
            "Type": "SecureString",
            "Overwrite": True,
            "KeyId": "alias/parameter_store_key"
        }
        send_ssm_request("AmazonSSM.PutParameter", json.dumps(req))

        if tags:
            tag_list = []
            for t in tags:
                if '=' in t:
                    k, v = t.split('=', 1)
                    tag_list.append({"Key": k, "Value": v})
            if tag_list:
                tag_req = {
                    "ResourceId": name,
                    "ResourceType": "Parameter",
