    kRegion = sign(kDate, regionName)
    kService = sign(kRegion, serviceName)
    return sign(kService, 'aws4_request')

def send_ssm_request(target, payload):
    method = 'POST'
    service = 'ssm'
    region = os.environ.get('AWS_REGION', 'us-east-1')
    endpoint = os.environ.get('AWS_ENDPOINT_URL', f'https://ssm.{region}.amazonaws.com')

    if endpoint.startswith('http://'):
        host = endpoint.split('http://')[1].split('/')[0]
    elif endpoint.startswith('https://'):
        host = endpoint.split('https://')[1].split('/')[0]
    else:
        host = endpoint

    access_key = os.environ.get('AWS_ACCESS_KEY_ID', 'test')
    secret_key = os.environ.get('AWS_SECRET_ACCESS_KEY', 'test')
    session_token = os.environ.get('AWS_SESSION_TOKEN', '')

    t = datetime.datetime.utcnow()
    amzdate = t.strftime('%Y%m%dT%H%M%SZ')
    datestamp = t.strftime('%Y%m%d')

    canonical_uri = '/'
    canonical_querystring = ''
    payload_hash = hashlib.sha256(payload.encode('utf-8')).hexdigest()

    headers = {
        'Content-Type': 'application/x-amz-json-1.1',
        'Host': host,
        'X-Amz-Date': amzdate,
        'X-Amz-Target': target,
    }
    if session_token:
        headers['X-Amz-Security-Token'] = session_token

    canonical_headers = ''
    signed_headers = ''
    for k in sorted(headers.keys()):
        canonical_headers += f"{k.lower()}:{headers[k]}\n"
        signed_headers += f"{k.lower()};"
    signed_headers = signed_headers[:-1]

    canonical_request = f"{method}\n{canonical_uri}\n{canonical_querystring}\n{canonical_headers}\n{signed_headers}\n{payload_hash}"

    algorithm = 'AWS4-HMAC-SHA256'
    credential_scope = f"{datestamp}/{region}/{service}/aws4_request"
    string_to_sign = f"{algorithm}\n{amzdate}\n{credential_scope}\n{hashlib.sha256(canonical_request.encode('utf-8')).hexdigest()}"

    signing_key = get_signature_key(secret_key, datestamp, region, service)
    signature = hmac.new(signing_key, string_to_sign.encode('utf-8'), hashlib.sha256).hexdigest()

    headers['Authorization'] = f"{algorithm} Credential={access_key}/{credential_scope}, SignedHeaders={signed_headers}, Signature={signature}"

    req = urllib.request.Request(endpoint, data=payload.encode('utf-8'), headers=headers)
    try:
        resp = urllib.request.urlopen(req)
        return json.loads(resp.read().decode('utf-8'))
    except urllib.error.HTTPError as e:
        body = e.read().decode('utf-8')
        try:
            err = json.loads(body)
            msg = err.get('message', err.get('Message', body))
            print(f"Error: {msg}", file=sys.stderr)
        except:
            print(f"Error: {body}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error: {str(e)}", file=sys.stderr)
        sys.exit(1)

