            print(val)
        else:
            desc = describe_parameters(service)
            p = next((x for x in desc if x['Name'] == name), {})
            ver = "0"
            ts = format_date(p.get('LastModifiedDate', 0)) if p else "1970-01-01 00:00:00"
            user = p.get('LastModifiedUser', '') if p else ""
            rows = [
                ['Key', 'Value', 'Version', 'LastModified', 'User'],
                [key, val, ver, ts, user]
            ]
            print(format_table(rows), end='')

    elif cmd == 'history':
        args = [a for a in sys.argv[2:] if not a.startswith('-')]
        if len(args) < 2: return
        service, key = args[0], args[1]
        name = f"/{service}/{key}"
