            ver = "0"
            ts = format_date(p.get('LastModifiedDate', 0))
            user = p.get('LastModifiedUser', '')
            rows.append([event, ver, ts, user])
        print(format_table(rows), end='')

    elif cmd == 'env':
        args = [a for a in sys.argv[2:] if not a.startswith('-')]
