        out = {}
        for p in params:
            key = p['Name'].split('/')[-1]
            out[key] = p['Value']
        print(json.dumps(out))

    elif cmd == 'delete':
        args = [a for a in sys.argv[2:] if not a.startswith('-')]
        if len(args) < 2: return
        service, key = args[0], args[1]
        name = f"/{service}/{key}"
        req = {"Name": name}
