                if '=' in t:
                    k, v = t.split('=', 1)
                    tag_list.append({"Key": k, "Value": v})
            if tag_list:
                tag_req = {
                    "ResourceId": name,
                    "ResourceType": "Parameter",
                    "Tags": tag_list
                }
