            if sys.argv[i] in ('-t', '--tags'):
                if i + 1 < len(sys.argv):
                    tags = sys.argv[i+1].split(',')
                    i += 2
                else:
                    i += 1
                continue
            if sys.argv[i].startswith('--tags='):
                tags = sys.argv[i].split('=', 1)[1].split(',')
                i += 1
                continue
            if sys.argv[i].startswith('-') and sys.argv[i] != '-':
                i += 1
                continue
            args.append(sys.argv[i])
            i += 1

        if len(args) < 3: return
        service, key, value = args[0], args[1], args[2]
        if value == '-':
            value = sys.stdin.read()
        name = f"/{service}/{key}"

        req = {
            "Description": "1",
            "Name": name,
            "Value": value,
            "Type": "SecureString",
            "Overwrite": True,
            "KeyId": "alias/parameter_store_key"
        }
        send_ssm_request("AmazonSSM.PutParameter", json.dumps(req))

        if tags:
            tag_list = []
            for t in tags:
                if '=' in t:
                    k, v = t.split('=', 1)
                    tag_list.append({"Key": k, "Value": v})
            if tag_list:
                tag_req = {
                    "ResourceId": name,
                    "ResourceType": "Parameter",
                    "Tags": tag_list
                }
                send_ssm_request("AmazonSSM.AddTagsToResource", json.dumps(tag_req))

    elif cmd == 'exec':
        services = []
        exec_args = []
        found_dash = False
        i = 2
        while i < len(sys.argv):
            if sys.argv[i] == '--':
                found_dash = True
                exec_args = sys.argv[i+1:]
                break
            if not sys.argv[i].startswith('-'):
                services.append(sys.argv[i])
            i += 1

        if not found_dash or not exec_args:
            return

        env_updates = {}
        for s in services:
            params = get_parameters_by_path(s)
            for p in params:
                k = p['Name'].split('/')[-1].upper()
                env_updates[k] = p['Value']

        if '--pristine' in sys.argv:
            new_env = env_updates
        else:
            new_env = os.environ.copy()
            new_env.update(env_updates)

        try:
            os.execvpe(exec_args[0], exec_args, new_env)
        except OSError as e:
            print(f"chamber: exec failed: {e}", file=sys.stderr)
            sys.exit(1)

if __name__ == '__main__':
    main()
